UPDATE books SET title='A assombração da Casa da Colina',genre='Terror gótico',synopsis='Quatro desconhecidos chegam a uma casa que guarda lembranças. Para Eleanor, o convite parece uma chance de pertencer. A casa parece concordar.',note='Preste atenção às pequenas crueldades à mesa. Quando as paredes começarem a bater, a casa já estará viva.' WHERE slug='hill-house';
UPDATE books SET title='Os salgueiros',genre='Terror folclórico',synopsis='Dois viajantes ficam presos em uma ilha do Danúbio. Enquanto a água sobe, os salgueiros começam a se mover contra o vento.',note='Uma leitura curta para uma noite de ventania. O céu aberto pode ser tão sufocante quanto um quarto fechado.' WHERE slug='willows';
UPDATE books SET title='Carmilla',genre='Terror gótico',synopsis='Uma visitante fascinante chega a uma propriedade isolada. Laura acolhe sua nova companhia enquanto uma doença misteriosa se espalha pela região.',note='Uma história íntima e lenta, em que cada gesto de afeto pode esconder uma ameaça.' WHERE slug='carmilla';
UPDATE books SET title='O Rei de Amarelo',genre='Terror cósmico',synopsis='Uma peça proibida atravessa histórias de artistas, cidades perturbadoras e um lugar distante chamado Carcosa. Alguns leitores nunca voltam do segundo ato.',note='Leia os primeiros contos de uma vez. As pequenas conexões fazem a cidade inteira parecer febril.' WHERE slug='king-in-yellow';
UPDATE books SET title='Frankenstein',genre='Terror gótico',synopsis='Victor Frankenstein dá vida a uma criatura e a abandona. A perseguição entre criador e criação vai dos Alpes até as margens do Ártico.',note='Acompanhe a criatura aprendendo a ler e observando uma família pela fresta da parede.' WHERE slug='frankenstein';
UPDATE books SET title='A volta do parafuso',genre='Terror psicológico',synopsis='Uma jovem governanta cuida de duas crianças em uma casa de campo. O que ela vê do outro lado do lago muda a forma como interpreta cada palavra delas.',note='Leia com alguém. Uma pequena mudança de interpretação pode revelar duas casas completamente diferentes.' WHERE slug='turn-of-the-screw';
UPDATE books SET title='Drácula',genre='Terror gótico',synopsis='Cartas, diários e notícias revelam a chegada de uma presença antiga à Inglaterra. Um grupo improvável precisa aprender a enfrentar o conde.',note='Um clássico de ritmo surpreendente, contado pelas vozes de quem tenta entender a ameaça.' WHERE slug='dracula';
UPDATE books SET title='O retrato de Dorian Gray',genre='Terror psicológico',synopsis='Um jovem deseja conservar sua beleza enquanto um retrato recebe as marcas de suas escolhas. O desejo cobra um preço.',note='Observe como a conversa elegante se transforma aos poucos em uma história de horror.' WHERE slug='dorian-gray';
UPDATE books SET title='O chamado de Cthulhu',genre='Terror cósmico',synopsis='Anotações e relatos dispersos levam um investigador a uma presença adormecida e a um culto que atravessa continentes.',note='Uma investigação feita de fragmentos. Cada descoberta amplia a sensação de insignificância.' WHERE slug='cthulhu';
UPDATE books SET title='O corvo e outros poemas',genre='Terror gótico',synopsis='Luto, lembranças e visitantes noturnos atravessam esta seleção de poemas de um dos grandes nomes da literatura de horror.',note='Leia em voz alta para perceber o peso das repetições e o ritmo das imagens.' WHERE slug='raven';
UPDATE books SET title='A pata do macaco',genre='Terror sobrenatural',synopsis='Um objeto trazido de longe promete realizar três desejos. Uma família descobre que até o pedido mais simples pode ter consequências terríveis.',note='Uma sala comum, uma noite de chuva e três desejos bastam para construir o medo.' WHERE slug='monkey-paw';
UPDATE books SET title='O horror de Dunwich',genre='Terror cósmico',synopsis='Uma família isolada, um nascimento estranho e livros proibidos anunciam uma ameaça nas colinas de Dunwich.',note='Uma paisagem rural em que cada detalhe parece esconder algo maior.' WHERE slug='horror-dunwich';
UPDATE editions SET format=CASE format WHEN 'Paperback' THEN 'Brochura' WHEN 'Hardcover' THEN 'Capa dura' ELSE format END;
